import fs from 'node:fs';
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import ts from 'typescript';
const require=createRequire(import.meta.url);
require.extensions['.ts']=(module,filename)=>{const out=ts.transpileModule(fs.readFileSync(filename,'utf8'),{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.CommonJS,esModuleInterop:true,resolveJsonModule:true}});module._compile(out.outputText,filename);};
const E=require('../lib/engine.ts'),D=require('../lib/defaults.ts'),M=require('../lib/model.ts'),I=require('../lib/import-export.ts');
let passed=0;
function test(name,f){try{f();passed++;console.log('PASS '+name);}catch(e){console.error('FAIL '+name);throw e;}}
function base(){const s=D.initialState(false);s.eligibilityConfirmed=true;s.hosts=[{...M.newHost(),id:'h',quantity:1,sockets:2,coresPerSocket:12,rightsConfirmed:true}];s.workloads=[{...M.newWorkload('h'),id:'w',quantity:1,cores:2,osVersion:'none',sql:[{...M.newSql(),id:'sq'}]}];return s;}
function close(a,b){assert.ok(Math.abs(a-b)<0.000001,`${a} != ${b}`);}
test('Real retail snapshot picks production version-specific SQL meters',()=>{const s=base();assert.equal(s.prices.meters['sql-2016-Standard'].rate,.19);assert.equal(s.prices.meters['sql-2014-Enterprise'].rate,.74);assert.equal(s.prices.meters['windows-2016-Standard'].rate,.007132);});
test('SQL four-core floor and exact UTC catch-up',()=>{const s=base();s.start='2026-10-15';s.months=1;const e=E.estimate(s);assert.equal(e.lines[0].units,4);close(e.catchup,E.hours('2026-07-15',s.start)*4*.19);close(e.recurring,E.hours(s.start,'2026-11-15')*4*.19);assert.ok(e.complete);});
test('Same SQL version does not duplicate charges; highest edition wins',()=>{const s=base();const q=s.workloads[0].sql[0];s.workloads[0].sql.push({...q,id:'q2',edition:'Enterprise'});const e=E.estimate(s);assert.equal(e.lines.length,1);assert.equal(e.lines[0].edition,'Enterprise');close(e.recurring,E.hours(s.start,E.addMonths(s.start,s.months))*4*.74);});
test('Different SQL versions create separate ESU groups',()=>{const s=base();s.workloads[0].sql.push({...M.newSql(),version:'2014'});assert.equal(E.estimate(s).lines.length,2);assert.ok(E.estimate(s).missing.some(x=>x.includes('year 1')));});
test('SQL 2014 missing historical coverage is quote-required, not zero',()=>{const s=base();s.workloads[0].sql[0].version='2014';const e=E.estimate(s);assert.equal(e.complete,false);assert.equal(e.missing.length,2);s.prices.annual['sql-2014-Standard']=[100,200,300];close(E.estimate(s).prior,4*300);});
test('Existing Arc coverage only back-bills the gap',()=>{const s=base();s.workloads[0].sql[0].coverage={mode:'arc',paidThrough:'2026-10-10',priorYears:0};close(E.estimate(s).catchup,4*24*4*.19);});
test('Annual mid-year enrollment buys full current year and missing prior years',()=>{const s=base();s.workloads[0].sql[0].version='2014';s.prices.annual['sql-2014-Standard']=[100,200,300];const e=E.estimate(s,'annual');close(e.total,4*(100+200+300));close(e.prior,4*300);close(e.annual,4*300);});
test('Annual costs are never prorated after early migration',()=>{const s=base();s.prices.annual['sql-2016-Standard']=[100,200,300];const e=E.estimate(s,'annual');const cut=Object.fromEntries(e.lines.map(l=>[l.id,'2026-10-20']));close(E.estimate(s,'annual',cut).total,400);});
test('Windows virtual floors use Standard ESU despite Datacenter base edition',()=>{const s=base();s.workloads[0].sql=[];s.workloads[0].osVersion='2016';s.workloads[0].osEdition='Datacenter';const e=E.estimate(s);assert.equal(e.lines[0].units,8);assert.equal(e.lines[0].edition,'Standard');assert.equal(E.estimate(s,'annual').lines[0].edition,'Datacenter');});
test('Windows physical Standard stacks full host cores for each two OSEs',()=>{const s=base();s.hosts[0].windowsMode='standard';s.workloads[0].osVersion='2016';s.workloads[0].quantity=5;s.workloads[0].sql=[];assert.equal(E.estimate(s).lines[0].units,24*3);s.hosts[0].windowsMode='datacenter';assert.equal(E.estimate(s).lines[0].units,24);});
test('Windows no pre-EOS recurring bill or catch-up',()=>{const s=base();s.workloads[0].sql=[];s.workloads[0].osVersion='2016';s.months=1;const e=E.estimate(s);close(e.total,0);s.months=6;assert.ok(E.estimate(s).recurring>0);close(E.estimate(s).catchup,0);});
test('Expired program is a coverage gap, not a free coverage promise',()=>{const s=base();s.workloads[0].sql[0].version='2012';const e=E.estimate(s);assert.equal(e.lines[0].status,'expired');assert.equal(e.complete,false);assert.equal(e.coverageGaps.length,1);});
test('Future unsupported program is unpriced after EOS',()=>{const s=base();s.workloads[0].sql[0].version='2017';s.months=24;assert.ok(E.estimate(s).missing.some(x=>x.includes('future ESU')));});
test('New Azure policy waives SQL2014 but not SQL2016',()=>{const s=base();s.hosts[0].location='azure';s.workloads[0].sql[0].version='2014';close(E.estimate(s).total,0);s.workloads[0].sql[0].version='2016';assert.ok(E.estimate(s).total>0);});
test('Azure Local SQL2014 needs Azure verification',()=>{const s=base();s.hosts[0].location='azurelocal';s.workloads[0].sql[0].version='2014';assert.equal(E.estimate(s).lines[0].free,false);s.hosts[0].azureVerified=true;assert.equal(E.estimate(s).lines[0].free,true);});
test('SQL Enterprise unlimited virtualization does not bill guest cores again',()=>{const s=base();s.hosts[0].sqlMode='enterprise';s.workloads[0].quantity=10;s.workloads[0].cores=8;const e=E.estimate(s);assert.equal(e.lines[0].units,24);assert.equal(e.lines[0].edition,'Enterprise');});
test('Bare-metal SQL remains separately billed under a host ESU pool',()=>{const s=base();s.hosts[0].sqlMode='enterprise';s.workloads.push({...M.newWorkload('h'),kind:'physical',osVersion:'none',sql:[M.newSql()]});assert.equal(E.estimate(s).lines.length,2);});
test('SQL PAYG adds base software cost',()=>{const s=base();s.workloads[0].sql[0].entitlement='payg';const e=E.estimate(s);close(e.base,E.hours(s.start,e.end)*4*.1);});
test('No SA and Server+CAL cannot silently get Arc ESU',()=>{for(const ent of ['none','servercal']){const s=base();s.workloads[0].sql[0].entitlement=ent;assert.equal(E.estimate(s).complete,false);}});
test('Catch-up and recurring discounts are independent',()=>{const s=base(),a=E.estimate(s);s.discount=10;s.backDiscount=20;const b=E.estimate(s);close(b.recurring,a.recurring*.9);close(b.catchup,a.catchup*.8);});
test('Monthly cash-flow sums exactly to charge ledger',()=>{for(const months of [1,3,6,12,36]){const s=base();s.months=months;const e=E.estimate(s);close(e.total,e.months.reduce((n,m)=>n+m.total,0));}});
test('Partial migration leaves shared physical core ESU in place',()=>{const s=base();s.hosts[0].sqlMode='enterprise';s.workloads[0].migrate=true;s.workloads.push({...M.newWorkload('h'),osVersion:'none',sql:[M.newSql()]});const m=E.migration(s);close(m.esuAvoided,0);assert.equal(m.partialPools.length,1);});
test('MI migration only removes OS if the OS is decommissioned',()=>{const s=base();s.workloads[0].osVersion='2016';s.workloads[0].migrate=true;const a=E.migration(s);s.workloads[0].retireOS=true;const b=E.migration(s);assert.ok(b.esuAvoided>a.esuAvoided);});
test('Insufficient AHB licenses retains paid SQL license cost',()=>{const s=base();s.mi.ahb=true;s.mi.ahbConfirmed=true;s.mi.ahbCores=0;const m=E.miCost(s);assert.equal(m.ahbValid,false);assert.ok(m.license>0);assert.ok(m.missing.length);s.mi.ahbCores=4;assert.equal(E.miCost(s).license,0);});
test('MI Enterprise GP ratio is four target vCores per eligible core',()=>{const s=base();assert.equal(E.miCost(s).requiredCores,4);s.mi.tier='bc';assert.equal(E.miCost(s).requiredCores,16);s.mi.ahbEdition='Standard';assert.equal(E.miCost(s).requiredCores,64);});
test('Storage rounds to 32GB, subtracts included space, multiplies instances',()=>{const s=base();s.mi.storageGB=33;close(E.miCost(s).storage,32*.115*2);});
test('Reservation is term price and full cash commitment appears in forecast',()=>{const s=base();s.workloads[0].migrate=true;s.mi.term='three';s.mi.cutover=s.start;s.mi.overlapMonths=0;const m=E.migration(s);close(m.mi.commitment,1800*16);assert.ok(m.miRun>=m.mi.commitment);close(m.mi.compute,1800*16/36);});
test('No MI run charges when cutover and overlap are outside forecast',()=>{const s=base();s.mi.cutover='2030-01-01';s.mi.overlapMonths=1;close(E.migration(s).miRun,0);});
test('JSON scenario round-trip and invalid data rejected',()=>{const s=base();assert.deepEqual(I.validateState(JSON.parse(JSON.stringify(s))),s);assert.throws(()=>I.validateState({...s,months:-4}));assert.throws(()=>I.validateState({...s,start:'2026-02-31'}));assert.throws(()=>I.validateState({...s,hosts:[]}));});
test('CSV handles commas, CRLF, quotes, and multiple SQL versions on one OSE',()=>{assert.deepEqual(I.parseCSV('a,b\r\n"one, two","three""four"\r\n'),[['a','b'],['one, two','three"four']]);const s=base();const csv='host,workload,vcores,os_version,sql_version\nH,SQL,4,2016,2014\nH,SQL,4,2016,2016';const a=I.importInventory(csv,s);assert.equal(a.workloads.length,1);assert.equal(a.workloads[0].sql.length,2);assert.throws(()=>I.importInventory('host,workload,vcores,os_version\nH,SQL,-4,2016',s));});
test('CSV export protects spreadsheet formula prefixes',()=>{assert.equal(I.csvEscape('=SUM(A1)'),`"'=SUM(A1)"`);});
test('Base SQL PAYG is not doubled for different installed ESU versions',()=>{const s=base();s.workloads[0].sql[0].entitlement='payg';s.workloads[0].sql.push({...M.newSql(),version:'2014',entitlement:'payg',coverage:{mode:'new',paidThrough:'',priorYears:2}});const e=E.estimate(s);close(e.base,E.hours(s.start,e.end)*4*.1);});
test('SQL PAYG continues for supported versions without an ESU charge',()=>{const s=base();s.workloads[0].sql[0].version='2022';s.workloads[0].sql[0].entitlement='payg';const e=E.estimate(s);close(e.base,E.hours(s.start,e.end)*4*.1);close(e.recurring,0);});
test('A passive checkbox cannot exempt one version while another is active',()=>{const s=base();s.workloads[0].sql[0].exempt=true;s.workloads[0].sql.push({...M.newSql(),version:'2014'});assert.ok(E.estimate(s).lines.every(l=>!l.free));});
console.log(`\n${passed} calculation and import checks passed.`);
